content:
{
  "baking_tools": {
    "name_en": "Bakeware & baking utensils",
    "name_zh": "烘焙工具",
    "definition": "Bakeware and utensils used for preparing, shaping, or baking cakes, cookies, and other baked goods, such as cake tins and cookie cutters.",
    "boundary": "In: cake tins, cookie cutters, baking pans, rolling pins, pastry brushes. Out: cake stands, cake cases, serving plates, mixing bowls, kitchen gadgets."
  },
  "bath_beauty": {
    "name_en": "Bath & beauty accessories",
    "name_zh": "洗浴美容配件",
    "definition": "Reusable bathroom and personal-care accessories for washing, drying, or holding bath products, including towels, soap holders, and bath sponges.",
    "boundary": "In: bath towels, soap dishes, bath sponges, washcloths. Out: consumable toiletries, cosmetics, candles, kitchen textiles."
  },
  "bunting_garland": {
    "name_en": "Bunting & garlands",
    "name_zh": "彩旗挂饰",
    "definition": "Decorative hanging strings of flags or shaped paper/fabric pieces used for party, seasonal, or home decoration.",
    "boundary": "In: fabric/paper bunting, honeycomb paper garlands, birthday garlands. Out: individual hanging ornaments, tabletop decorations, wall art, tinsel."
  },
  "cake_cases": {
    "name_en": "Cake cases",
    "name_zh": "蛋糕纸杯",
    "definition": "Disposable paper or foil cups used to line muffin or fairy cake tins for baking individual cakes.",
    "boundary": "In: fairy cake cases, cupcake liners, muffin cases. Out: cake tins, paper cups for drinks, napkins, cake stands."
  },
  "cake_stand": {
    "name_en": "Cake stands",
    "name_zh": "蛋糕架",
    "definition": "Pedestal or tiered stands used to display and serve cakes, desserts, or pastries.",
    "boundary": "In: glass/metal/ceramic cake stands, tiered stands, hanging cake stands. Out: cake tins, plates, serving trays, cup stands."
  },
  "candle_holder_lantern": {
    "name_en": "Candle holders & lanterns",
    "name_zh": "烛台灯笼",
    "definition": "Items designed to hold candles or tea lights, including candlesticks, tealight holders, lanterns, and candle plates.",
    "boundary": "In: candle holders, tealight holders, candelabras, lanterns intended for candles. Out: candles themselves, incense holders, electric lamps, oil burners."
  },
  "incense": {
    "name_en": "Incense",
    "name_zh": "香薰",
    "definition": "Incense sticks, cones, and sets with holders or burners used to produce fragrance when burned.",
    "boundary": "In: incense sticks, incense cones, incense/candle gift sets, incense holders. Out: candles, wax melts, essential oil diffusers, air fresheners."
  },
  "clocks": {
    "name_en": "Clocks",
    "name_zh": "时钟",
    "definition": "Wall and table clocks with functional timekeeping faces, used to tell time and decorate interiors.",
    "boundary": "In: wall clocks, table clocks, mantel clocks. Out: watches, kitchen timers, decorative non-functional clock ornaments, alarm clocks (if not decorative)."
  },
  "clothing_slippers": {
    "name_en": "Slippers & soft wearable crafts",
    "name_zh": "拖鞋与手工饰品",
    "definition": "Indoor slippers, sock puppets, and small craft kits for making wearable accessories like scarves.",
    "boundary": "In: cosy slipper shoes, sock puppets, scarf knitting kits. Out: outdoor shoes, socks, gloves, hats, finished scarves."
  },
  "cushions_textiles": {
    "name_en": "Cushion covers",
    "name_zh": "靠垫套",
    "definition": "Decorative textile covers designed to fit and change the look of cushion pads or pillows.",
    "boundary": "In: cushion covers, pillow shams, throw pillow covers. Out: complete cushions with inserts, blankets, curtains, table linens, towels."
  },
  "doormats": {
    "name_en": "Doormats",
    "name_zh": "门垫",
    "definition": "Floor mats placed at entryways for wiping shoes and decorating the doorstep.",
    "boundary": "In: door mats, entrance mats, coir mats. Out: bath mats, rugs, carpets, kitchen mats."
  },
  "doorstops_paperweights": {
    "name_en": "Doorstops & paperweights",
    "name_zh": "门挡镇纸",
    "definition": "Weighted objects used to prop doors open or hold loose papers in place, often decorative.",
    "boundary": "In: decorative doorstops, paperweights, wedge doorstops. Out: bookends, furniture, wall hooks, heavy ornaments with no specific function."
  },
  "egg_cups": {
    "name_en": "Egg cups & cosies",
    "name_zh": "蛋杯蛋套",
    "definition": "Holders or cosies for boiled eggs, including cups, stands, and knitted/felt covers to keep eggs warm.",
    "boundary": "In: egg cups, egg cosies, hen-shaped egg warmers. Out: egg spoons, egg timers, egg plates, kitchen tools."
  },
  "furniture_knobs": {
    "name_en": "Cabinets & storage furniture",
    "name_zh": "橱柜储物家具",
    "definition": "Small freestanding or wall-mounted wooden cabinets and cupboards with drawers or doors, used for storage and display.",
    "boundary": "In: chests of drawers, wall cabinets, kitchen cupboards, hall cabinets. Out: individual furniture knobs/handles, shelving units without doors, wardrobes, bookshelves."
  },
  "garden_outdoor": {
    "name_en": "Garden & outdoor décor",
    "name_zh": "花园户外装饰",
    "definition": "Ornamental and functional garden items such as birdhouses, plant cages, garden markers, and mini decorative gardening sets.",
    "boundary": "In: birdhouses, plant cages/holders, garden markers, garden ornaments. Out: indoor planters/vases, pet bowls, outdoor furniture, garden tools (unless decorative mini set)."
  },
  "gift_boxes": {
    "name_en": "Gift boxes",
    "name_zh": "礼盒",
    "definition": "Decorative boxes for presenting gifts, including pre-boxed gift items like mugs or pens in gift packaging.",
    "boundary": "In: gift boxes, favour boxes, pre-boxed small gifts, presentation boxes. Out: gift wrap, gift bags, storage boxes, subscription boxes."
  },
  "gift_wrap_tags": {
    "name_en": "Gift wrap & tags",
    "name_zh": "礼品包装及标签",
    "definition": "Wrapping paper, gift wrap sets, and decorative wrapping tape used to wrap presents.",
    "boundary": "In: rolls/sheets of gift wrap, wrapping tape, gift wrap sets. Out: gift boxes, gift bags, ribbon/bows (unless part of set), greeting cards, stickers."
  },
  "greeting_cards": {
    "name_en": "Greeting cards",
    "name_zh": "贺卡",
    "definition": "Folded or flat cards with messages, sent or given for greetings, birthdays, holidays, and other occasions.",
    "boundary": "In: birthday cards, Christmas cards, occasion cards, packs of cards. Out: postcards, blank notecards, gift tags, party invitations."
  },
  "hand_warmer": {
    "name_en": "Hand warmers",
    "name_zh": "暖手宝",
    "definition": "Portable reusable or disposable warmers designed to heat hands or pockets.",
    "boundary": "In: hand warmers, pocket warmers, rechargeable hand warmers. Out: gloves, mittens, hot water bottles, scarves."
  },
  "hanging_ornaments": {
    "name_en": "Hanging ornaments",
    "name_zh": "挂饰",
    "definition": "Decorative ornaments with strings or hooks intended to hang from trees, walls, or other displays.",
    "boundary": "In: Christmas tree ornaments, hanging hearts/stars, feather hangers, wooden hanging decorations. Out: garlands/bunting, tabletop decorations, wall art, wreaths."
  },
  "tabletop_decorations": {
    "name_en": "Tabletop decorations",
    "name_zh": "桌面装饰",
    "definition": "Freestanding decorative figurines and ornaments designed to sit on tables, shelves, or mantelpieces.",
    "boundary": "In: Easter chicks, decorative birds, rabbit figurines, mini tabletop Christmas trees. Out: hanging ornaments, wall art, candle holders, vases/planters, garlands."
  },
  "storage_baskets_decor": {
    "name_en": "Storage baskets & picnic baskets",
    "name_zh": "储物篮野餐篮",
    "definition": "Decorative woven or fabric baskets used for storage, display, or carrying picnic items.",
    "boundary": "In: wicker baskets, stripe baskets, picnic baskets, French-style baskets. Out: storage boxes with lids, laundry hampers, planters, trash bins."
  },
  "hooks_racks_shelves": {
    "name_en": "Hooks, racks & shelves",
    "name_zh": "挂钩架搁板",
    "definition": "Wall-mounted or freestanding hooks, racks, shelves, and coat hangers for hanging and organising items.",
    "boundary": "In: coat hooks, wall racks, decorative shelves, magazine racks with hooks. Out: freestanding cabinets, furniture, door signs, curtain rods."
  },
  "hot_water_bottle": {
    "name_en": "Hot water bottles",
    "name_zh": "热水袋",
    "definition": "Rubber or thermoplastic bottles designed to be filled with hot water for warmth, often with decorative covers.",
    "boundary": "In: hot water bottles with or without covers, rubber hot water bottles. Out: hand warmers, heating pads, ice packs, cushions."
  },
  "jumbo_shopper_bag": {
    "name_en": "Jumbo shopper bags",
    "name_zh": "大号购物袋",
    "definition": "Large reusable shopping bags and totes, typically made of cotton or fabric, for carrying groceries or purchases.",
    "boundary": "In: jumbo shopper bags, large cotton totes, shopping bags. Out: handbags, purses, lunch bags, gift bags, luggage."
  },
  "keyrings_tags": {
    "name_en": "Keyrings & charms",
    "name_zh": "钥匙扣挂件",
    "definition": "Small decorative items attached to keys, bags, or phones, including keyrings, bag charms, and phone charms.",
    "boundary": "In: keychains, bag charms, phone charms, key tags. Out: jewellery, zipper pulls, luggage tags, badges/pins."
  },
  "kitchen_storage": {
    "name_en": "Kitchen storage",
    "name_zh": "厨房储物",
    "definition": "Containers and jars for storing food and kitchen items, including tins, jars, and bread bins.",
    "boundary": "In: biscuit tins, bread bins, glass storage jars, canisters. Out: cookware, kitchen tools, decorative vases, planters, bathroom storage."
  },
  "kitchen_textiles": {
    "name_en": "Kitchen textiles",
    "name_zh": "厨房纺织品",
    "definition": "Fabric items used in the kitchen for protection, drying, and handling hot items, such as aprons, tea towels, and oven gloves.",
    "boundary": "In: aprons, tea towels, oven gloves, pot holders. Out: tablecloths, napkins, placemats, cushion covers, bath towels."
  },
  "kitchen_tools": {
    "name_en": "Kitchen tools & utensils",
    "name_zh": "厨房工具餐具",
    "definition": "Hand-held tools and small utensils for food preparation, cooking, and serving, including spoons, chopsticks, and milk pans.",
    "boundary": "In: serving spoons, egg spoons, chopsticks, milk pans, kitchen gadgets. Out: bakeware (cake tins/cookie cutters), cutlery sets, dinnerware, kitchen storage."
  },
  "lights_lamps": {
    "name_en": "Lights & lampshades",
    "name_zh": "灯饰灯罩",
    "definition": "Decorative electric or battery-powered lighting such as string lights, fairy lights, and lampshades, used for illumination and ambience.",
    "boundary": "In: string lights, cherry lights, lampshades, decorative lamps, fairy lights. Out: candles, candle holders, lanterns without electric light, ceiling fixtures."
  },
  "lunch_bag": {
    "name_en": "Lunch bags",
    "name_zh": "午餐包",
    "definition": "Soft insulated or fabric bags designed for carrying packed lunches and snacks.",
    "boundary": "In: insulated lunch bags, fabric lunch totes. Out: hard lunch boxes, paper bags, shopper bags, picnic baskets."
  },
  "lunch_box_cutlery": {
    "name_en": "Lunch boxes with cutlery",
    "name_zh": "带餐具午餐盒",
    "definition": "Lunch boxes that include cutlery sets, and separate compact cutlery sets for meals on the go.",
    "boundary": "In: lunch boxes with cutlery, mini cutlery sets. Out: soft lunch bags, full-size cutlery, kitchen utensils, bento boxes without cutlery."
  },
  "magnets": {
    "name_en": "Fridge magnets",
    "name_zh": "冰箱贴",
    "definition": "Decorative magnets, often food-shaped or novelty, designed to attach to refrigerators or magnetic surfaces.",
    "boundary": "In: fridge magnets, magnetic memo holders, novelty magnets. Out: magnetic clips, non-magnetic ornaments, stickers, wall decals."
  },
  "mirrors": {
    "name_en": "Mirrors",
    "name_zh": "镜子",
    "definition": "Reflective glass surfaces in decorative frames for wall or tabletop use, including compact mirrors.",
    "boundary": "In: wall mirrors, table mirrors, compact mirrors, jewellery-framed mirrors. Out: mirrored wall art (if separate), mirror trays, furniture with mirrors, decorative glass."
  },
  "mugs_cups": {
    "name_en": "Mugs & cups",
    "name_zh": "杯具",
    "definition": "Individual drinking vessels for hot or cold beverages, including mugs, cups, and coffee cup & saucer sets.",
    "boundary": "In: mugs, cups, coffee cups with saucers. Out: teapots, coffee pots, travel tumblers, glassware, plates."
  },
  "notebooks_journals": {
    "name_en": "Notebooks & journals",
    "name_zh": "笔记本日记本",
    "definition": "Bound paper books for writing, sketching, or journaling, including notebooks, journals, and sketchbooks.",
    "boundary": "In: notebooks, journals, sketchbooks, diaries. Out: loose paper, greeting cards, stationery sets, address books."
  },
  "party_bags_supplies": {
    "name_en": "Party bags & supplies",
    "name_zh": "派对用品袋",
    "definition": "Party favours and accessories for celebrations, including party bags, balloons, party cones, and invitations.",
    "boundary": "In: party bags, balloons, party cones, party invites, small favours. Out: party tableware, bunting/garlands, cake cases, gift wrap."
  },
  "party_tableware": {
    "name_en": "Party tableware",
    "name_zh": "派对餐具",
    "definition": "Disposable paper tableware for parties, such as napkins, paper cups, and paper plates.",
    "boundary": "In: paper napkins, paper cups, paper plates, table covers. Out: reusable tableware, party bags, balloons, bunting, cake cases."
  },
  "pens_pencils_art": {
    "name_en": "Pens, pencils & art supplies",
    "name_zh": "文具艺术用品",
    "definition": "Writing and drawing instruments and related art supplies, including pencils, pens, and eraser sets.",
    "boundary": "In: pencils, pens, coloured pencils, erasers, mini pencil sets. Out: stationery sets, pencil cases, notebooks."
  },
  "pet_items": {
    "name_en": "Pet bowls & accessories",
    "name_zh": "宠物碗具配件",
    "definition": "Bowls and feeding accessories for household pets, primarily cats and dogs.",
    "boundary": "In: dog bowls, cat bowls, pet feeding dishes. Out: pet food, pet toys, pet beds, leashes, wild bird items."
  },
  "photo_frame_album": {
    "name_en": "Photo frames & albums",
    "name_zh": "相框相册",
    "definition": "Frames and albums for displaying or storing photographs, often decorative.",
    "boundary": "In: picture frames, photo albums, photoframes. Out: wall art, mirrors, shadow boxes, scrapbooks."
  },
  "plates": {
    "name_en": "Plates",
    "name_zh": "盘子",
    "definition": "Individual flat or shallow dishes used for serving or eating food, including decorative plates.",
    "boundary": "In: dinner plates, cake plates, pizza plates, decorative plates. Out: bowls, platters, cake stands, paper plates, trays."
  },
  "tableware_sets": {
    "name_en": "Tableware accessories & sets",
    "name_zh": "餐具配件套装",
    "definition": "Coordinated table setting accessories such as napkin rings, napkin charms, and place card holders.",
    "boundary": "In: napkin rings, napkin charms, place settings, table decorating sets. Out: dinnerware sets, cutlery sets, glassware, tablecloths/napkins."
  },
  "purse_wallet": {
    "name_en": "Purses & wallets",
    "name_zh": "钱包手拿包",
    "definition": "Small bags and wallets for carrying money, cards, or cosmetics, including coin purses and cosmetic purses.",
    "boundary": "In: coin purses, wallets, cosmetic purses, small clutch purses. Out: handbags, shopper totes, luggage, keyrings/bag charms."
  },
  "sewing_craft": {
    "name_en": "Sewing & craft kits",
    "name_zh": "缝纫手工套件",
    "definition": "Sewing kits and felt craft kits for making dolls, accessories, or other handmade items.",
    "boundary": "In: sewing kits, felt craft kits, doll-making kits, felt handbag kits. Out: finished textiles, knitting kits, painting kits, general craft supplies."
  },
  "door_hangers_signs": {
    "name_en": "Door signs & number tiles",
    "name_zh": "门牌号码牌",
    "definition": "Decorative signs, number/letter tiles, and door hangers used for labelling rooms, doors, or house numbers.",
    "boundary": "In: number tiles, door signs, name plaques, house number signs. Out: clocks, wall art, mirrors, hooks/racks, furniture."
  },
  "travel_bags_luggage": {
    "name_en": "Travel bags & luggage",
    "name_zh": "旅行箱包",
    "definition": "Bags and luggage designed for travel or picnics, including cabin bags, airline bags, and picnic bags.",
    "boundary": "In: cabin bags, airline bags, travel duffels, picnic bags. Out: everyday handbags, shopper bags, lunch bags, laptop bags."
  },
  "stickers_tattoos": {
    "name_en": "Stickers & temporary tattoos",
    "name_zh": "贴纸纹身贴",
    "definition": "Decorative adhesive stickers and temporary tattoos used for crafting, decorating, or personalising items.",
    "boundary": "In: stickers, 3D stickers, sticker sheets, temporary tattoos. Out: gift wrap, labels, magnets, wall decals."
  },
  "teapot_tea_set": {
    "name_en": "Teapots & tea/coffee sets",
    "name_zh": "茶壶茶具套装",
    "definition": "Teapots, coffee pots, and coordinated tea/coffee serving pieces such as mugs, cups, saucers, and storage caddies.",
    "boundary": "In: teapots, coffee pots, tea sets, matching mugs/cups/saucers, coffee caddies. Out: standalone individual mugs/cups (see Mugs & cups), kettles, dinnerware."
  },
  "tissues_plasters": {
    "name_en": "Tissues & plasters",
    "name_zh": "纸巾创可贴",
    "definition": "Decorative pocket tissue packs and adhesive plasters designed for personal care or gifting.",
    "boundary": "In: pocket tissues, decorative tissue packs, adhesive bandages/plasters. Out: paper napkins, paper towels, wipes, medical kits."
  },
  "trinket_jewellery_box": {
    "name_en": "Trinket, jewellery & sewing boxes",
    "name_zh": "首饰盒杂物盒",
    "definition": "Small decorative boxes for storing jewellery, trinkets, sewing supplies, or as tissue box covers.",
    "boundary": "In: jewellery boxes, trinket boxes, sewing boxes, fabric oval/heart boxes, tissue box covers. Out: storage baskets, gift boxes, furniture cabinets, generic storage containers."
  },
  "umbrella_rainwear": {
    "name_en": "Umbrellas & parasols",
    "name_zh": "雨伞遮阳伞",
    "definition": "Hand-held umbrellas and decorative parasols for rain protection or shade.",
    "boundary": "In: folding umbrellas, decorative parasols, ruffled umbrellas. Out: raincoats, rain hats, hand warmers, sun hats."
  },
  "vases_planters": {
    "name_en": "Vases & planters",
    "name_zh": "花瓶花盆",
    "definition": "Containers for displaying cut flowers or growing plants, including vases, plant pots, and wall planters.",
    "boundary": "In: vases, plant pots, planters, wall planters, small decorative pots. Out: garden outdoor birdhouses/plant cages, bowls, storage jars, candle holders."
  },
  "word_blocks_letters": {
    "name_en": "Wooden word blocks & letters",
    "name_zh": "木质字母块",
    "definition": "Decorative wooden letters or blocks arranged to spell words for home decoration.",
    "boundary": "In: wooden block letters, word signs made of separate letters, letter blocks. Out: number tiles, door signs, alphabet blocks for children, wall art with printed words."
  },
  "wall_art": {
    "name_en": "Wall art & plaques",
    "name_zh": "墙艺挂画",
    "definition": "Decorative wall hangings, plaques, and mirrored wall decorations intended for wall

{
  "baking_tools": {
    "name_en": "Baking Tools & Tins",
    "name_zh": "烘焙工具和模具",
    "definition": "Items used for baking, including cake tins and cookie cutters.",
    "boundary": "Includes baking pans, moulds, and cutters; excludes general kitchen utensils (kitchen_tools) and disposable paper cases (cake_cases)."
  },
  "bath_beauty": {
    "name_en": "Bath & Beauty Accessories",
    "name_zh": "洗浴美容用品",
    "definition": "Towels, soap holders, and bath sponges used for personal care in the bath or shower.",
    "boundary": "Includes bath linens and bath accessories; excludes kitchen textiles (kitchen_textiles) and tissues (tissues_plasters)."
  },
  "bunting_garland": {
    "name_en": "Bunting & Garlands",
    "name_zh": "彩旗和花环",
    "definition": "Decorative strings of flags or paper shapes used to adorn spaces for celebrations.",
    "boundary": "Includes paper or fabric garlands and bunting; excludes individual hanging ornaments (hanging_ornaments)."
  },
  "cake_cases": {
    "name_en": "Cake Cases",
    "name_zh": "蛋糕纸托",
    "definition": "Disposable paper or foil cups used to line muffin or fairy cake tins.",
    "boundary": "Includes baking paper liners; excludes reusable cake tins (baking_tools) and paper napkins/cups (party_tableware)."
  },
  "cake_stand": {
    "name_en": "Cake Stands",
    "name_zh": "蛋糕架",
    "definition": "Elevated plates or stands used to display and serve cakes and desserts.",
    "boundary": "Includes glass, metal, or ceramic cake stands; excludes general serving plates (plates) and tabletop decorations (tabletop_decorations)."
  },
  "candle_holder_lantern": {
    "name_en": "Candle Holders & Lanterns",
    "name_zh": "烛台和灯笼",
    "definition": "Holders, plates, or lanterns designed to safely contain candles or tea lights.",
    "boundary": "Includes candle plates and tea light holders; excludes string lights (lights_lamps) and incense holders (incense)."
  },
  "incense": {
    "name_en": "Incense",
    "name_zh": "香薰产品",
    "definition": "Incense sticks, cones, or sets used to release fragrance when burned.",
    "boundary": "Includes incense with holders or candles in sets; excludes candle holders without incense (candle_holder_lantern) and scented candles alone."
  },
  "clocks": {
    "name_en": "Clocks",
    "name_zh": "时钟",
    "definition": "Timepieces designed for wall or tabletop display.",
    "boundary": "Includes wall clocks and table clocks; excludes watches or alarm clocks not intended as decor."
  },
  "clothing_slippers": {
    "name_en": "Clothing & Slippers",
    "name_zh": "服装和拖鞋",
    "definition": "Wearable items such as slippers, sock puppets, and scarf knitting kits.",
    "boundary": "Includes slippers, soft sock puppets, and knitting kits for scarves; excludes hand warmers (hand_warmer) and purses/wallets (purse_wallet)."
  },
  "cushions_textiles": {
    "name_en": "Cushion Covers",
    "name_zh": "靠垫套",
    "definition": "Removable fabric covers designed to fit over cushion inserts.",
    "boundary": "Includes decorative cushion covers only; excludes filled cushions, throws, and kitchen textiles."
  },
  "doormats": {
    "name_en": "Doormats",
    "name_zh": "门垫",
    "definition": "Mats placed at entrances to wipe shoes and protect floors.",
    "boundary": "Includes indoor/outdoor doormats; excludes bath mats and pet mats."
  },
  "doorstops_paperweights": {
    "name_en": "Doorstops & Paperweights",
    "name_zh": "门挡和镇纸",
    "definition": "Weighted items used to hold doors open or keep papers in place.",
    "boundary": "Includes decorative doorstops and paperweights; excludes tabletop decorations (tabletop_decorations) not designed as weights."
  },
  "egg_cups": {
    "name_en": "Egg Cups & Egg Cosies",
    "name_zh": "蛋杯和蛋套",
    "definition": "Items used to hold boiled eggs upright or cover them to keep warm.",
    "boundary": "Includes egg cups and knitted/felt egg cosies; excludes general kitchen tools (kitchen_tools) and tableware (plates)."
  },
  "furniture_knobs": {
    "name_en": "Cabinets & Cupboards",
    "name_zh": "橱柜",
    "definition": "Small freestanding or wall-mounted storage furniture pieces such as cabinets and cupboards.",
    "boundary": "Includes decorative storage cabinets with drawers; excludes wall shelves/hooks (hooks_racks_shelves), storage baskets, and separate furniture knobs/handles."
  },
  "garden_outdoor": {
    "name_en": "Garden & Outdoor Decor",
    "name_zh": "花园户外装饰",
    "definition": "Decorative and functional items for gardens and outdoor spaces, such as birdhouses, plant cages, and garden markers.",
    "boundary": "Includes garden ornaments and plant holders; excludes indoor vases/planters (vases_planters) and pet bowls (pet_items)."
  },
  "gift_boxes": {
    "name_en": "Gift Boxes",
    "name_zh": "礼品盒",
